@js:
(function() {
    var list = [];
    var now = new Date().getTime();
    var usr = Math.floor(Math.random() * 90000000 + 10000000);
    function getRankUrl(sectionId) {
        var s = sign('timestamp=' + now + '&usr=' + usr);
        return 'https://dj.palmestore.com/zybk/api/category/tagbook?usr=' + usr + '&sign=' + encodeURIComponent(s) + '&pageSize=20&sectionId=' + sectionId + '&currentPage={{page}}&timestamp=' + now + '&p3=25255056&freqKey=-1&today=0';
    }
    function getTagUrl(tagId) {
        var s = sign('timestamp=' + now + '&usr=' + usr);
        return 'https://dj.palmestore.com/zybk/api/category/data?usr=' + usr + '&tagId=' + tagId + '&isTop=1&sign=' + encodeURIComponent(s) + '&tagType=2&page={{page}}&timestamp=' + now + '&p3=25255056&p4=501656&p5=19&p21=3&p22=10&p25=25255156&p26=29&p28=f1a07127cc32ede2';
    }
    function addItem(title, url) {
        list.push({
            title: title,
            url: url,
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: 0.25
            }
        });
    }
    function addTitle(title) {
        list.push({
            title: title,
            url: null,
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: 1
            }
        });
    }
    addTitle('🔥 男生排行 🔥');
    var maleRanks = [
        ['推荐榜', '38819'],
        ['热读榜', '130001'],
        ['原创榜', '930001'],
        ['新书榜', '130002'],
        ['完本榜', '130003'],
        ['热搜榜', '130004'],
        ['高分榜', '130005']
    ];
    maleRanks.forEach(function(item) {
        addItem(item[0], getRankUrl(item[1]));
    });
    addTitle('🌸 女生排行 🌸');
    var femaleRanks = [
        ['推荐榜', '38808'],
        ['热读榜', '130006'],
        ['新书榜', '130007'],
        ['完本榜', '130008'],
        ['原创榜', '930002'],
        ['热搜榜', '130009'],
        ['高分榜', '130010']
    ];
    femaleRanks.forEach(function(item) {
        addItem(item[0], getRankUrl(item[1]));
    });
    var s1 = sign('timestamp=' + now + '&usr=' + usr);
    var url1 = 'https://dj.palmestore.com/zybk/api/rank/tag?usr=' + usr + '&sign=' + encodeURIComponent(s1) + '&id=13&timestamp=' + now + '&p2=124012&p3=25255056&p4=501656&p5=19&p25=25255156';
    var res1 = JSON.parse(java.ajax(url1));
    var maleTags = [];
    if (res1.body) {
        res1.body.forEach(function(item) {
            if (item.item) {
                item.item.forEach(function(i) {
                    maleTags.push({ title: i.name, value: i.tagId });
                });
            }
        });
    }
    addTitle('🔥 男标签 🔥');
    maleTags.forEach(function(tag) {
        addItem(tag.title, getTagUrl(tag.value));
    });
    var s2 = sign('timestamp=' + now + '&usr=' + usr);
    var url2 = 'https://dj.palmestore.com/zybk/api/rank/tag?usr=' + usr + '&sign=' + encodeURIComponent(s2) + '&id=14&timestamp=' + now + '&p2=124012&p3=25255056&p4=501656&p5=19&p25=25255156';
    var res2 = JSON.parse(java.ajax(url2));
    var femaleTags = [];
    if (res2.body) {
        res2.body.forEach(function(item) {
            if (item.item) {
                item.item.forEach(function(i) {
                    femaleTags.push({ title: i.name, value: i.tagId });
                });
            }
        });
    }
    addTitle('🌸 女标签 🌸');
    femaleTags.forEach(function(tag) {
        addItem(tag.title, getTagUrl(tag.value));
    });
    return JSON.stringify(list);
})();

source.jsLib:
var javaImport = new JavaImporter();
javaImport.importPackage(
    Packages.java.lang,
    Packages.java.security,
    Packages.java.security.spec,
    Packages.java.util
);

var privateKey = "";

function sign(p) {
    with (javaImport) {
        var priPKCS8 = PKCS8EncodedKeySpec(Base64.getDecoder().decode(privateKey));
        var keyf = KeyFactory.getInstance("RSA");
        var priKey = keyf.generatePrivate(priPKCS8);
        var signature = Signature.getInstance("SHA1WithRSA");
        signature.initSign(priKey);
        signature.update(new String(p).getBytes("UTF-8"));
        return Base64.getEncoder().encodeToString(signature.sign());
    }
}

